import {
  clientsDelete,
  clientsGet,
  clientsPost,
  clientsPut,
  type ClientsResult,
} from "@/lib/clientsApi";

import type {
  AddFacilityRequest,
  AddFacilityResponse,
  PsRunSearchResponse,
  CompanyInfoFields,
  StaffListResponse,
  CompanySummary,
  ResyncConflict,
  PreviewResyncResponse,
  ConflictResolution,
  ApplyResyncResponse,
  ManualLinkWorkflow,
  ManualLinkRequest,
  ManualLinkResponse,
} from "@/types/generated";

// Generated by ts-rs from the Rust structs in `unitprep-api` (`api/clients_companies.rs`,
// `clients_resync/`, `clients_manual_link.rs`); see `types/generated/README.md`.
export type {
  CompanySummary,
  ResyncConflict,
  PreviewResyncResponse,
  ConflictResolution,
  ApplyResyncResponse,
  ManualLinkWorkflow,
  ManualLinkRequest,
  ManualLinkResponse,
  CompanyInfoFields,
  StaffListResponse,
  AddFacilityRequest,
  AddFacilityResponse,
  PsRunSearchResponse,
};

// The plain unfiltered company list (`GET /clients`, `listCompanies`) was
// retired with the last page that read it; the Clients page uses the
// filtered directory query in `lib/clientsDirectory.ts`, and every other
// page reads the company it is scoped to from the company detail.

export async function archiveCompany(
  companyId: string,
): Promise<ClientsResult<undefined>> {
  return clientsPost(`/clients/${companyId}/archive`);
}

export async function unarchiveCompany(
  companyId: string,
): Promise<ClientsResult<undefined>> {
  return clientsPost(`/clients/${companyId}/unarchive`);
}

/**
 * Marks a company's implementation completed (`completed: true`) or
 * reopens it. Both directions are idempotent on the backend
 * (`api::clients_implementation_status`); needs `client_ops.perform`.
 */
export async function setImplementationCompleted(
  companyId: string,
  completed: boolean,
): Promise<ClientsResult<undefined>> {
  const path = `/clients/${companyId}/implementation-completed`;
  // The PUT carries no payload -- the path is the whole request.
  return completed ? clientsPut(path, undefined) : clientsDelete(path);
}

/**
 * Permanently deletes a company and every facility under it -- distinct
 * from archive/unarchive above, which is reversible and keeps the row
 * around. For a genuine mistake (a test import, or one created from the
 * wrong Process Street runs), not something to reach for as routine
 * cleanup. The frontend confirms before calling this; the backend
 * itself asks for no separate confirmation of its own.
 */
export async function deleteCompany(
  companyId: string,
): Promise<ClientsResult<undefined>> {
  return clientsDelete(`/clients/${companyId}`);
}

export async function previewResync(
  companyId: string,
): Promise<ClientsResult<PreviewResyncResponse>> {
  return clientsPost(`/clients/${companyId}/resync/preview`);
}

export async function applyResync(
  companyId: string,
  resolutions: ConflictResolution[],
): Promise<ClientsResult<ApplyResyncResponse>> {
  return clientsPost(`/clients/${companyId}/resync/apply`, { resolutions });
}

/**
 * Company page's "Manual Link" button -- repoints one facility's Intake
 * or Merchant Account run to a different run id, in place, whether or
 * not it's already linked to something else. See the backend module's
 * own doc comment for why this exists alongside (not instead of) the
 * Elavon tab's own "Link Manually", which only covers the not-yet-linked
 * Merchant Account case.
 */
export async function manualLink(
  companyId: string,
  request: ManualLinkRequest,
): Promise<ClientsResult<ManualLinkResponse>> {
  return clientsPost(`/clients/${companyId}/manual-link`, request);
}

/**
 * Saves the company page's hand-edited fields. Every changed field is
 * protected from the next Process Street sync; needs `client_ops.perform`
 * (`api::clients_company_edit`).
 */
export async function updateCompanyInfo(
  companyId: string,
  fields: CompanyInfoFields,
): Promise<ClientsResult<undefined>> {
  return clientsPut(`/clients/${companyId}/info`, fields);
}

/** Assigns (or, with `null`, clears) the company's Implementation Manager. */
export async function setImplementationManager(
  companyId: string,
  userId: string | null,
): Promise<ClientsResult<undefined>> {
  return clientsPut(`/clients/${companyId}/implementation-manager`, {
    user_id: userId,
  });
}

/** Every active staff member -- the Implementation Manager picker's options. */
export async function listStaff(): Promise<ClientsResult<StaffListResponse>> {
  return clientsGet("/clients/staff");
}

/**
 * Typeahead over Process Street Intake runs for "Add facility" -- answered
 * from OO's synced copy (instant, as fresh as the last sync), never a live
 * Process Street call. Any authenticated caller.
 */
export async function searchPsRuns(
  q: string,
): Promise<ClientsResult<PsRunSearchResponse>> {
  return clientsGet(`/clients/ps-runs?q=${encodeURIComponent(q)}`);
}

/** Attaches one Process Street Intake run to the company as a facility. */
export async function addFacility(
  companyId: string,
  request: AddFacilityRequest,
): Promise<ClientsResult<AddFacilityResponse>> {
  return clientsPost(`/clients/${companyId}/facilities`, request);
}
